body:
@mthuret thank you so much, that works great. However, there seems to be a problem if i try this with a connectHierarchicalMenu, see the follwing example: 

```jsx
const ConnectedHierarchicalMenu = connectHierarchicalMenu(Categories);
const VirtualHierarchicalMenu = connectHierarchicalMenu(() => null);

const ConnectedSizes = connectRefinementList(Sizes);
const VirtualSizes = connectRefinementList(() => null);

const ConnectedBrands = connectRefinementList(Brands);
const VirtualBrands = connectRefinementList(() => null);

const ConnectedCondition = connectRefinementList(Condition);
const VirtualCondition = connectRefinementList(() => null);


 <InstantSearch
    appId=""
    apiKey=""
    indexName=''
    searchState = {this.props.searchState}

    onSearchStateChange={searchState => {
                
      if (!this.state.isClosing) {
        this.props.setSearchState(searchState); //save the searchState except when the modal is closing
      } else {
        this.setState({isClosing: false}); 
      }
    }}
  >
 
    <TouchableOpacity onPress = { () => this.setModalVisible(true) }>
      <Text> Show Modal </Text>
    </TouchableOpacity>

    <Modal
      animationType={'slide'}
      transparent={true}
      visible={ this.state.filterExpanded }
      onRequestClose={() => this.setState({isClosing: true})}
    >
      <ScrollView style={{flex: 1, marginTop: 30}}>
        <TouchableHighlight onPress={() => {
          this.setState({isClosing: true});
          this.setModalVisible(false);
        }}>
          <Text>Hide Modal</Text>
        </TouchableHighlight>

        <ConnectedCurrentRefinements />
        <ConnectedHierarchicalMenu attributes = {['categories.level0', 'categories.level1']} />
        <ConnectedSizes attributeName = "size_tid"  />
        <ConnectedBrands attributeName = "brand_tid"  />
        <ConnectedCondition attributeName = "condition"  />

      </ScrollView>
    </Modal>
    
    <VirtualHierarchicalMenu attributes={['categories.level0','categories.level1']} />
    <VirtualSizes attributeName="size_tid" />      
    <VirtualBrands attributeName="brand_tid" />      
    <VirtualCondition attributeName="condition" />   

    <ConnectedHits/> 

</InstantSearch>
```
The follwing error is displayed: Cannot declare two hierarchical facets with the same name: `categories.level0`

Any ideas?
